using System.Data;
using System.Text.Json;
using backend.Data;
using backend.DTOs;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;
namespace backend.Services;
public sealed class ThematicMapService(AppDbContext context,IOptions<ThematicMapOptions> options):IThematicMapService
{
 private readonly ThematicMapOptions _options=options.Value;
 public async Task<ThematicMapResponse<ThematicGridCellDto>> GetNearestStopDistanceAsync(ThematicExtentRequest e,bool walking,CancellationToken ct) {
  Validate(e); var estimate=Estimate(e); if(estimate>_options.MaximumGridCellCount) throw new ThematicMapValidationException($"Seçilen alan yaklaşık {estimate:N0} hücre üretiyor. En fazla {_options.MaximumGridCellCount:N0} hücreye izin verilir; lütfen haritayı yakınlaştırın.");
  const string sql="""WITH bounds AS (SELECT ST_Transform(ST_MakeEnvelope(@minLon,@minLat,@maxLon,@maxLat,4326),3857) geom), cells AS (SELECT row_number() OVER () id, ST_Intersection(ST_MakeEnvelope(ST_XMin(b.geom)+ix*@size,ST_YMin(b.geom)+iy*@size,ST_XMin(b.geom)+(ix+1)*@size,ST_YMin(b.geom)+(iy+1)*@size,3857),b.geom) geom FROM bounds b CROSS JOIN LATERAL generate_series(0,(CEIL((ST_XMax(b.geom)-ST_XMin(b.geom))/@size)-1)::int) ix CROSS JOIN LATERAL generate_series(0,(CEIL((ST_YMax(b.geom)-ST_YMin(b.geom))/@size)-1)::int) iy) SELECT c.id,ST_AsGeoJSON(ST_Transform(c.geom,4326)),ST_X(ST_Transform(ST_Centroid(c.geom),4326)),ST_Y(ST_Transform(ST_Centroid(c.geom),4326)),s."Id",s."Name",ST_Distance(ST_Transform(ST_Centroid(c.geom),4326)::geography,s."Geometry"::geography) FROM cells c CROSS JOIN LATERAL (SELECT st."Id",st."Name",st."Geometry" FROM "TblTransportStops" st WHERE st."IsActive" AND NOT st."IsDeleted" AND st."Geometry" IS NOT NULL ORDER BY st."Geometry" <-> ST_Transform(ST_Centroid(c.geom),4326) LIMIT 1) s ORDER BY c.id""";
  var result=new List<ThematicGridCellDto>(); await using var cmd=context.Database.GetDbConnection().CreateCommand(); cmd.CommandText=sql; Add(cmd,"minLon",e.MinLongitude);Add(cmd,"minLat",e.MinLatitude);Add(cmd,"maxLon",e.MaxLongitude);Add(cmd,"maxLat",e.MaxLatitude);Add(cmd,"size",_options.GridCellSizeMeters); if(cmd.Connection!.State!=ConnectionState.Open)await cmd.Connection.OpenAsync(ct); await using var reader=await cmd.ExecuteReaderAsync(ct);
  while(await reader.ReadAsync(ct)){var d=reader.GetDouble(6);var min=d/_options.WalkingSpeedMetersPerSecond/60;result.Add(new(){Id=$"cell-{reader.GetInt64(0)}",Geometry=Parse(reader.GetString(1)),CenterLongitude=reader.GetDouble(2),CenterLatitude=reader.GetDouble(3),NearestStopId=reader.GetInt32(4),NearestStopName=reader.GetString(5),DistanceMeters=Math.Round(d,1),WalkingDurationMinutes=walking?Math.Round(min,1):null,Category=walking?WalkClass(min):DistanceClass(d)});}
  var avg=result.Count==0?0:result.Average(x=>x.DistanceMeters);var best=walking?"VeryShort":"VeryClose";var worst=walking?"Long":"Far";return new(){ThemeType=walking?"WalkingTime":"NearestStopDistance",Features=result,Summary=new{totalCells=result.Count,averageDistanceMeters=Math.Round(avg,1),averageWalkingMinutes=Math.Round(avg/_options.WalkingSpeedMetersPerSecond/60,1),bestClassCellCount=result.Count(x=>x.Category==best),worstClassCellCount=result.Count(x=>x.Category==worst)}};
 }
 public async Task<ThematicMapResponse<ThematicRouteDto>> GetRouteDensityAsync(ThematicExtentRequest e,CancellationToken ct){Validate(e);const string sql="""SELECT r."Id",r."Name",r."Color",ST_AsGeoJSON(r."Geometry"),COUNT(s."Id")::int,ST_Length(r."Geometry"::geography) FROM "TblTransportRoutes" r LEFT JOIN "TblTransportStops" s ON s."RouteId"=r."Id" AND s."IsActive" AND NOT s."IsDeleted" AND s."Geometry" IS NOT NULL WHERE r."IsActive" AND NOT r."IsDeleted" AND r."Geometry" IS NOT NULL AND r."Geometry" && ST_MakeEnvelope(@minLon,@minLat,@maxLon,@maxLat,4326) AND ST_Intersects(r."Geometry",ST_MakeEnvelope(@minLon,@minLat,@maxLon,@maxLat,4326)) GROUP BY r."Id",r."Name",r."Color",r."Geometry" ORDER BY r."Id" ASC""";var routes=new List<ThematicRouteDto>();await using var cmd=context.Database.GetDbConnection().CreateCommand();cmd.CommandText=sql;Add(cmd,"minLon",e.MinLongitude);Add(cmd,"minLat",e.MinLatitude);Add(cmd,"maxLon",e.MaxLongitude);Add(cmd,"maxLat",e.MaxLatitude);if(cmd.Connection!.State!=ConnectionState.Open)await cmd.Connection.OpenAsync(ct);await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct)){var len=reader.GetDouble(5);var count=reader.GetInt32(4);routes.Add(new(){RouteId=reader.GetInt32(0),RouteName=reader.GetString(1),RouteColor=reader.GetString(2),Geometry=Parse(reader.GetString(3)),ActiveStopCount=count,RouteLengthMeters=Math.Round(len,1),StopsPerKilometer=len>0?Math.Round(count/(len/1000),2):0});}var ordered=routes.OrderBy(x=>x.ActiveStopCount).ToList();for(var i=0;i<ordered.Count;i++)ordered[i].DensityClass=i<ordered.Count*.25?"Low":i<ordered.Count*.5?"Medium":i<ordered.Count*.75?"High":"VeryHigh";var top=routes.OrderByDescending(x=>x.ActiveStopCount).FirstOrDefault();return new(){ThemeType="RouteDensity",Features=routes,Summary=new{routeCount=routes.Count,densestRoute=top?.RouteName,maximumStopCount=top?.ActiveStopCount??0,averageStopCount=routes.Count==0?0:Math.Round(routes.Average(x=>x.ActiveStopCount),1)}};}
 private void Validate(ThematicExtentRequest e){if(!new[]{e.MinLongitude,e.MinLatitude,e.MaxLongitude,e.MaxLatitude}.All(double.IsFinite)||e.MinLongitude < -180||e.MaxLongitude>180||e.MinLatitude < -85||e.MaxLatitude>85||e.MinLongitude>=e.MaxLongitude||e.MinLatitude>=e.MaxLatitude)throw new ThematicMapValidationException("Extent geçersiz. EPSG:4326 koordinatlarını ve min/max sırasını kontrol edin.");}
 private int Estimate(ThematicExtentRequest e){const double r=6371000;var lat=(e.MinLatitude+e.MaxLatitude)/2*Math.PI/180;var w=(e.MaxLongitude-e.MinLongitude)*Math.PI/180*r*Math.Cos(lat);var h=(e.MaxLatitude-e.MinLatitude)*Math.PI/180*r;return (int)Math.Ceiling(w/_options.GridCellSizeMeters)*(int)Math.Ceiling(h/_options.GridCellSizeMeters);}
 private static string DistanceClass(double d)=>d<300?"VeryClose":d<700?"Close":d<1200?"Medium":"Far"; private static string WalkClass(double m)=>m<5?"VeryShort":m<10?"Short":m<15?"Medium":"Long";private static JsonElement Parse(string value)=>JsonDocument.Parse(value).RootElement.Clone();private static void Add(System.Data.Common.DbCommand c,string n,object v){var p=c.CreateParameter();p.ParameterName=n;p.Value=v;c.Parameters.Add(p);}
}
